-- All 36 club IDs already exist. Only link them to a new canonical competition,
-- retaining every original team identity and record. No production writes.
do $italy_b$
declare
 lid constant uuid := 'b2602027-8c4e-54c6-a6d6-000000000001';
 clubs uuid[] := array['00569c78-42e1-4640-9eda-74e475e2f6d0','057cdd3d-ae06-4bdc-81cb-d5cc546faff4','060b9cc6-ee4f-49de-9f52-041b1659bf58','10003fcd-48bd-4727-892d-3d0365323619','143cc422-e4ca-42d6-8695-c3dcc9b04d0d','16480fe4-f14c-47bf-b9b5-19efd257c425','26eee4ff-0e9a-4547-ac32-4951ef08d573','2c738e6d-bcb5-4faf-95f5-eb9c32eccbb3','36ca461a-6a29-4a1c-a4b3-5ebbb3eb2115','38680007-e2df-4558-b585-139d0b74411b','5512c9ac-a50a-4436-b5e7-961036407aea','556ba16a-9851-419d-8cee-507d8a98d9ca','55ac1cf3-4c31-4815-9bfe-9d71af5f4825','61461ba4-8fc9-4ea7-9f48-c13b545d5e27','64362e1c-0e9a-4c8e-82c9-840a3cf996ec','935019ac-5117-4e73-954d-3a6bb7ca9114','a138f18a-187b-479b-908e-9eaf8294781b','a31ba911-1405-4d8a-812d-e5b1564b2cc5','a3d3c1af-7228-47f5-8f04-cdae1b065162','a686d321-cea1-446b-af07-011cd4794487','a8b6edfb-ec57-4ff1-9d7f-14052b98fbc6','ac2414b7-d25b-49e2-b15e-9ed1e853081e','b8082ede-fabd-4e17-8500-e2150ac9e1bf','bab7adaa-8115-46df-968f-37ef5679fa01','c2e540ff-9baf-411c-b98c-f10f00dbeb1e','c3f57f90-7df3-4bde-a730-21a1a5199244','c71045f7-7275-4a7a-a400-9467eab96a79','cc5a330a-30b5-4a2e-a84a-f2cc0a7a37e1','df9a2b9a-0746-4ea8-b09d-da190e9411db','e0113861-fa41-4c4c-a815-bb9ee4e9c319','e28fa35d-bb54-4ede-b736-2ded1593b039','e5dd37ac-df02-4f05-a0fa-cc3c933b4b3a','ec3a7bab-2047-48b8-a832-d412790f5de3','ed22da58-ada3-44e4-8c5d-6f83b0b6df1d','ed45e3f5-b33f-48ad-98ce-ab15274ec538','f3da7305-9f68-46a7-ada3-dbc7d65e6947']::uuid[];
begin
 if exists(select 1 from pg_temp.ld1_leagues where id=lid and (name is distinct from 'Serie B Nazionale' or country is distinct from 'Italy' or season is distinct from '2026-27' or basketball_type is distinct from 'mens' or active is not true))
 or exists(select 1 from pg_temp.ld1_leagues where id<>lid and country='Italy' and basketball_type='mens' and (lower(name) like '%serie b nazionale%' or lower(name)='serie b'))
 or (select count(*) from pg_temp.ld1_teams t join (values ('00569c78-42e1-4640-9eda-74e475e2f6d0'::uuid,'Treviglio Brianza Basket'),('057cdd3d-ae06-4bdc-81cb-d5cc546faff4'::uuid,'Ristopro Fabriano'),('060b9cc6-ee4f-49de-9f52-041b1659bf58'::uuid,'Andrea Costa Imola'),('10003fcd-48bd-4727-892d-3d0365323619'::uuid,'Logiman Orzinuovi'),('143cc422-e4ca-42d6-8695-c3dcc9b04d0d'::uuid,'Luiss Roma'),('16480fe4-f14c-47bf-b9b5-19efd257c425'::uuid,'Infodrive Capo d''Orlando'),('26eee4ff-0e9a-4547-ac32-4951ef08d573'::uuid,'Siaz Basket Piazza Armerina'),('2c738e6d-bcb5-4faf-95f5-eb9c32eccbb3'::uuid,'Benacquista Latina'),('36ca461a-6a29-4a1c-a4b3-5ebbb3eb2115'::uuid,'Dany Quarrata'),('38680007-e2df-4558-b585-139d0b74411b'::uuid,'Umana San Giobbe Chiusi'),('5512c9ac-a50a-4436-b5e7-961036407aea'::uuid,'Luxarm Lumezzane'),('556ba16a-9851-419d-8cee-507d8a98d9ca'::uuid,'Tema Sinergie Faenza'),('55ac1cf3-4c31-4815-9bfe-9d71af5f4825'::uuid,'Pallacanestro Viola Reggio Calabria'),('61461ba4-8fc9-4ea7-9f48-c13b545d5e27'::uuid,'Fiorenzuola Bees'),('64362e1c-0e9a-4c8e-82c9-840a3cf996ec'::uuid,'Moncada Energy Agrigento'),('935019ac-5117-4e73-954d-3a6bb7ca9114'::uuid,'Legnano Knights'),('a138f18a-187b-479b-908e-9eaf8294781b'::uuid,'Cestistica San Severo'),('a31ba911-1405-4d8a-812d-e5b1564b2cc5'::uuid,'A2A Leonessa Brescia'),('a3d3c1af-7228-47f5-8f04-cdae1b065162'::uuid,'S4 Energia Vicenza'),('a686d321-cea1-446b-af07-011cd4794487'::uuid,'Basketball Club Lucca'),('a8b6edfb-ec57-4ff1-9d7f-14052b98fbc6'::uuid,'Adamant Ferrara'),('ac2414b7-d25b-49e2-b15e-9ed1e853081e'::uuid,'UCC Assigeco Piacenza'),('b8082ede-fabd-4e17-8500-e2150ac9e1bf'::uuid,'Rucker San Vendemiano'),('bab7adaa-8115-46df-968f-37ef5679fa01'::uuid,'Rimadesio Desio'),('c2e540ff-9baf-411c-b98c-f10f00dbeb1e'::uuid,'Virtus Roma 1960'),('c3f57f90-7df3-4bde-a730-21a1a5199244'::uuid,'Pielle Livorno'),('c71045f7-7275-4a7a-a400-9467eab96a79'::uuid,'Fabo Herons Montecatini'),('cc5a330a-30b5-4a2e-a84a-f2cc0a7a37e1'::uuid,'Fulgor Basket Omegna'),('df9a2b9a-0746-4ea8-b09d-da190e9411db'::uuid,'Loreto Pesaro'),('e0113861-fa41-4c4c-a815-bb9ee4e9c319'::uuid,'Solbat Golfo Piombino'),('e28fa35d-bb54-4ede-b736-2ded1593b039'::uuid,'OraSì Ravenna'),('e5dd37ac-df02-4f05-a0fa-cc3c933b4b3a'::uuid,'Liofilchem Roseto'),('ec3a7bab-2047-48b8-a832-d412790f5de3'::uuid,'Mens Sana Basketball Siena'),('ed22da58-ada3-44e4-8c5d-6f83b0b6df1d'::uuid,'Sangiorgese Basket'),('ed45e3f5-b33f-48ad-98ce-ab15274ec538'::uuid,'Felice Scandone Avellino'),('f3da7305-9f68-46a7-ada3-dbc7d65e6947'::uuid,'PSA Napoli Est')) e(id,name) on t.id=e.id and t.name=e.name where t.country='Italy' and t.basketball_type='mens' and t.active and t.league_name='Serie B Nazionale' and (t.league_id is null or t.league_id=lid))<>36
 or exists(select 1 from pg_temp.ld1_teams t where t.country='Italy' and t.basketball_type='mens' and t.active and (t.league_name='Serie B Nazionale' or t.league_id=lid) and t.id<>all(clubs))
 or exists(select 1 from pg_temp.ld1_memberships where league_id=lid and season='2026-27' and (team_id<>all(clubs) or active is not true))
 then raise exception 'Italian Serie B official identity or existing affiliation changed; review required';end if;
 insert into pg_temp.ld1_leagues(id,name,country,season,basketball_type,active) values(lid,'Serie B Nazionale','Italy','2026-27','mens',true) on conflict(id) do nothing;
 update pg_temp.ld1_teams set league_id=lid where id=any(clubs) and league_id is null;
 insert into pg_temp.ld1_memberships(id,team_id,league_id,season,active)
 select gen_random_uuid(),id,lid,'2026-27',true from unnest(clubs) id on conflict(team_id,league_id,season) do nothing;
 if (select count(*) from pg_temp.ld1_teams where league_id=lid and active)<>36 or (select count(*) from pg_temp.ld1_memberships where league_id=lid and season='2026-27' and active)<>36 then raise exception 'Serie B roster incomplete';end if;
end $italy_b$;
